package com.example.seniority.dto;

import java.time.LocalDate;

/**
 * Immutable DTO that mirrors one detail line from the original COBOL report.
 * Mirrors: DTL-ID, DTL-NAME, DTL-HIRE, DTL-YEARS, DTL-BAND
 */
public class SeniorityRecord {

    private final int    empId;
    private final String empName;
    private final LocalDate hireDate;
    private final double yearsOfService;   // e.g. 12.3  (like WS-YEARS  9(02)V9)
    private final String band;             // JUNIOR / MID / SENIOR / VETERAN

    public SeniorityRecord(int empId, String empName,
                           LocalDate hireDate,
                           double yearsOfService,
                           String band) {
        this.empId          = empId;
        this.empName        = empName;
        this.hireDate       = hireDate;
        this.yearsOfService = yearsOfService;
        this.band           = band;
    }

    public int       getEmpId()          { return empId; }
    public String    getEmpName()        { return empName; }
    public LocalDate getHireDate()       { return hireDate; }
    public double    getYearsOfService() { return yearsOfService; }
    public String    getBand()           { return band; }
}

