package com.example.seniority.dto;

/**
 * Band counters – mirrors WS-JUNIOR / WS-MID / WS-SENIOR / WS-VETERAN.
 */
public class SenioritySummary {
    private int junior  = 0;   // < 3 yrs
    private int mid     = 0;   // 3-7 yrs
    private int senior  = 0;   // 8-14 yrs
    private int veteran = 0;   // 15+ yrs

    public void incrementJunior()  { junior++;  }
    public void incrementMid()     { mid++;     }
    public void incrementSenior()  { senior++;  }
    public void incrementVeteran() { veteran++; }

    public int getJunior()  { return junior;  }
    public int getMid()     { return mid;     }
    public int getSenior()  { return senior;  }
    public int getVeteran() { return veteran; }
}

