package com.example.seniority.dto;

import java.util.List;

/** Aggregates detail rows + summary counters for the full report. */
public class SeniorityReport {
    private final List<SeniorityRecord> records;
    private final SenioritySummary      summary;

    public SeniorityReport(List<SeniorityRecord> records, SenioritySummary summary) {
        this.records = records;
        this.summary = summary;
    }

    public List<SeniorityRecord> getRecords() { return records; }
    public SenioritySummary      getSummary() { return summary; }
}

