package com.example.seniority.service;

import com.example.seniority.dto.SeniorityRecord;
import com.example.seniority.dto.SeniorityReport;
import com.example.seniority.dto.SenioritySummary;
import com.example.seniority.model.Employee;
import com.example.seniority.repository.EmployeeRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * Business-logic equivalent of CALC-SERVICE paragraph and the main report loop.
 *
 * Fixed "as-of" date: 2026-09-29  (WS-AS-OF-DATE = 20260929)
 * Years formula     : days / 365.25  (mirrors COBOL COMPUTE WS-YEARS)
 * Band thresholds   : < 3 → JUNIOR, < 8 → MID, < 15 → SENIOR, else VETERAN
 */
@Service
public class SeniorityService {

    /**
     * COBOL anchor: WS-AS-OF-DATE PIC 9(08) VALUE 20260929
     * This is intentionally fixed so the report is reproducible.
     */
    private static final LocalDate AS_OF_DATE = LocalDate.of(2026, 9, 29);

    private final EmployeeRepository employeeRepository;

    public SeniorityService(EmployeeRepository employeeRepository) {
        this.employeeRepository = employeeRepository;
    }

    /**
     * Reads all employees (mirrors READ loop), computes seniority for each
     * (mirrors CALC-SERVICE), and returns the assembled report.
     */
    @Transactional(readOnly = true)
    public SeniorityReport buildReport() {
        List<Employee>       employees = employeeRepository.findAll();
        List<SeniorityRecord> records  = new ArrayList<>();
        SenioritySummary     summary   = new SenioritySummary();

        for (Employee emp : employees) {
            SeniorityRecord rec = calcService(emp, summary);
            records.add(rec);
        }

        return new SeniorityReport(records, summary);
    }

    // ---------------------------------------------------------------
    // CALC-SERVICE paragraph – one employee at a time
    // ---------------------------------------------------------------

    /**
     * Mirrors the COBOL CALC-SERVICE paragraph exactly:
     *
     *   COMPUTE WS-DAYS  = INTEGER-OF-DATE(AS_OF) - INTEGER-OF-DATE(HIRE)
     *   COMPUTE WS-YEARS = WS-DAYS / 365.25
     *
     * COBOL's FUNCTION INTEGER-OF-DATE converts a Gregorian date (YYYYMMDD)
     * to the number of days since a fixed epoch (0001-01-01).  Java's
     * LocalDate.toEpochDay() uses 1970-01-01, so we use chronological
     * difference (asOf.toEpochDay() - hire.toEpochDay()) which preserves
     * the same arithmetic distance between dates.
     */
    SeniorityRecord calcService(Employee emp, SenioritySummary summary) {
        LocalDate hireDate = emp.getHireDate();

        // COMPUTE WS-DAYS = INTEGER-OF-DATE(AS_OF) - INTEGER-OF-DATE(HIRE)
        long wsDays = AS_OF_DATE.toEpochDay() - hireDate.toEpochDay();

        // COMPUTE WS-YEARS = WS-DAYS / 365.25
        // Result truncated to one decimal place to match PIC 9(02)V9
        double wsYearsRaw    = wsDays / 365.25;
        double wsYears       = Math.floor(wsYearsRaw * 10.0) / 10.0;  // truncate to 1 dp

        // EVALUATE TRUE  (band classification)
        String wsBand;
        if (wsYears < 3.0) {
            wsBand = "JUNIOR";
            summary.incrementJunior();
        } else if (wsYears < 8.0) {
            wsBand = "MID";
            summary.incrementMid();
        } else if (wsYears < 15.0) {
            wsBand = "SENIOR";
            summary.incrementSenior();
        } else {
            wsBand = "VETERAN";
            summary.incrementVeteran();
        }

        return new SeniorityRecord(
                emp.getEmpId(),
                emp.getEmpName(),
                hireDate,
                wsYears,
                wsBand
        );
    }
}

