package com.example.seniority.service;

import com.example.seniority.dto.SeniorityRecord;
import com.example.seniority.dto.SeniorityReport;
import com.example.seniority.dto.SenioritySummary;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Renders the {@link SeniorityReport} to a flat text file, reproducing the
 * exact column layout of the original COBOL RPT-FILE / RPT-LINE output.
 *
 * COBOL column widths preserved:
 *   ID    : 5 digits
 *   NAME  : 20 chars
 *   HIRE  : YYYY/MM/DD  (9 chars via PIC 9999/99/99)
 *   YEARS : Z9.9        (4 chars, leading zero suppressed)
 *   BAND  : 12 chars
 */
@Service
public class ReportWriterService {

    private static final Logger log = LoggerFactory.getLogger(ReportWriterService.class);

    private static final String SEP_LINE =
            "------------------------------------------------------------"; // 60 dashes
    private static final String TITLE    =
            "SENIORITY REPORT AS OF 2026-09-29";
    private static final String HEADER   =
            String.format("%-7s%-21s%-12s%-8s%-12s",
                    "ID", "NAME", "HIRE DATE", "YEARS", "BAND");

    @Value("${report.output.path:data/output/seniority.rpt}")
    private String outputPath;

    public void write(SeniorityReport report) {
        Path path = Paths.get(outputPath);
        try {
            Files.createDirectories(path.getParent());
        } catch (IOException e) {
            throw new UncheckedIOException("Cannot create output directory", e);
        }

        try (BufferedWriter bw = Files.newBufferedWriter(path, StandardCharsets.UTF_8)) {

            // Title + header block
            writeLine(bw, TITLE);
            writeLine(bw, SEP_LINE);
            writeLine(bw, HEADER);
            writeLine(bw, SEP_LINE);

            // Detail lines – mirrors WRITE RPT-LINE FROM DTL-LINE
            for (SeniorityRecord rec : report.getRecords()) {
                writeLine(bw, formatDetail(rec));
            }

            // Summary separator + band counts
            writeLine(bw, SEP_LINE);

            SenioritySummary s = report.getSummary();
            writeLine(bw, formatSummary("JUNIOR   (< 3 YRS)",  s.getJunior()));
            writeLine(bw, formatSummary("MID      (3-7 YRS)",  s.getMid()));
            writeLine(bw, formatSummary("SENIOR  (8-14 YRS)",  s.getSenior()));
            writeLine(bw, formatSummary("VETERAN (15+ YRS)",   s.getVeteran()));

        } catch (IOException e) {
            throw new UncheckedIOException("Failed to write seniority report", e);
        }

        log.info("SENIORTY: SENIORITY REPORT WRITTEN -> {}", path.toAbsolutePath());
    }

    // ---------------------------------------------------------------
    // Formatting helpers – mirror COBOL PICTURE clauses exactly
    // ---------------------------------------------------------------

    /**
     * Mirrors DTL-LINE structure:
     *   05 DTL-ID    PIC 9(05)
     *   05 FILLER    PIC X(02) SPACES
     *   05 DTL-NAME  PIC X(20)
     *   05 FILLER    PIC X(01) SPACES
     *   05 DTL-HIRE  PIC 9999/99/99
     *   05 FILLER    PIC X(03) SPACES
     *   05 DTL-YEARS PIC Z9.9
     *   05 FILLER    PIC X(03) SPACES
     *   05 DTL-BAND  PIC X(12)
     */
    private String formatDetail(SeniorityRecord rec) {
        String id    = String.format("%05d", rec.getEmpId());
        String name  = String.format("%-20.20s", rec.getEmpName());
        String hire  = String.format("%04d/%02d/%02d",
                rec.getHireDate().getYear(),
                rec.getHireDate().getMonthValue(),
                rec.getHireDate().getDayOfMonth());
        // PIC Z9.9 → suppress leading zero on tens digit only; always show units + 1dp
        String years = formatYears(rec.getYearsOfService());
        String band  = String.format("%-12.12s", rec.getBand());

        return id + "  " + name + " " + hire + "   " + years + "   " + band;
    }

    /**
     * Replicates COBOL PIC Z9.9:
     *   - Field is 4 characters wide: [tens][units].[tenths]
     *   - Leading tens digit is space if zero (zero-suppression).
     *   - Examples:  2.5 → " 2.5",  12.3 → "12.3",  0.7 → " 0.7"
     */
    private String formatYears(double years) {
        // Clamp to 0..99.9 to match PIC 9(02)V9 max storage
        double clamped = Math.min(99.9, Math.max(0.0, years));
        int    tens    = (int) (clamped / 10);
        int    units   = (int) (clamped % 10);
        int    tenth   = (int) Math.round((clamped - Math.floor(clamped)) * 10);
        char   tensChar = (tens == 0) ? ' ' : (char) ('0' + tens);
        return String.format("%c%d.%d", tensChar, units, tenth);
    }

    /**
     * Mirrors SUM-LINE:
     *   05 SUM-LABEL PIC X(20)
     *   05 SUM-COUNT PIC ZZ9
     */
    private String formatSummary(String label, int count) {
        // PIC ZZ9 → up to 3 digits, leading zeros suppressed
        String countStr = (count == 0) ? "  0"
                        : String.format("%3d", count).replace('0', ' ').stripTrailing();
        // Preserve exact ZZ9 behaviour: right-align, suppress leading zeros
        countStr = String.format("%3s", formatZZ9(count));
        return String.format("%-20.20s", label) + countStr;
    }

    /** PIC ZZ9: 3-char field, leading zeros suppressed (spaces). */
    private String formatZZ9(int value) {
        if (value >= 100) return String.valueOf(value);
        if (value >= 10)  return " " + value;
        return "  " + value;
    }

    private void writeLine(BufferedWriter bw, String line) throws IOException {
        bw.write(line);
        bw.newLine();
    }
}

