package com.example.seniority.runner;

import com.example.seniority.dto.SeniorityReport;
import com.example.seniority.service.ReportWriterService;
import com.example.seniority.service.SeniorityService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

/**
 * Entry point that wires together the service calls, mirroring the
 * COBOL MAIN-PARA:
 *   OPEN → write headers → PERFORM loop → write summary → CLOSE → DISPLAY → STOP RUN
 */
@Component
public class SeniorityRunner implements CommandLineRunner {

    private static final Logger log = LoggerFactory.getLogger(SeniorityRunner.class);

    private final SeniorityService    seniorityService;
    private final ReportWriterService reportWriterService;

    public SeniorityRunner(SeniorityService seniorityService,
                           ReportWriterService reportWriterService) {
        this.seniorityService    = seniorityService;
        this.reportWriterService = reportWriterService;
    }

    @Override
    public void run(String... args) {
        log.info("SENIORTY: starting seniority report generation");
        SeniorityReport report = seniorityService.buildReport();
        reportWriterService.write(report);
        // mirrors: DISPLAY "SENIORTY: SENIORITY REPORT WRITTEN"
        log.info("SENIORTY: SENIORITY REPORT WRITTEN");
    }
}

