package com.example.seniority.controller;

import com.example.seniority.dto.SeniorityReport;
import com.example.seniority.service.SeniorityService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Exposes the seniority report as a REST endpoint so the data can also be
 * consumed programmatically (no COBOL equivalent; added for Spring Boot idiom).
 */
@RestController
@RequestMapping("/api/seniority")
public class SeniorityController {

    private final SeniorityService seniorityService;

    public SeniorityController(SeniorityService seniorityService) {
        this.seniorityService = seniorityService;
    }

    /**
     * GET /api/seniority/report
     * Returns the full report DTO as JSON.
     */
    @GetMapping("/report")
    public ResponseEntity<SeniorityReport> getReport() {
        return ResponseEntity.ok(seniorityService.buildReport());
    }
}

