package com.example.seniority.service;

import com.example.seniority.dto.SeniorityRecord;
import com.example.seniority.dto.SenioritySummary;
import com.example.seniority.model.Employee;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import java.time.LocalDate;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

/**
 * Unit tests for CALC-SERVICE paragraph logic.
 * All expected values derived from running the original COBOL program
 * with AS_OF_DATE = 20260929.
 */
class SeniorityServiceTest {

    private SeniorityService service;

    @BeforeEach
    void setUp() {
        // EmployeeRepository not needed for unit testing calcService directly
        service = new SeniorityService(null);
    }

    @ParameterizedTest(name = "hire={0} expectBand={1} expectYearsApprox={2}")
    @CsvSource({
        "2024-08-19, JUNIOR,   2.1",   // < 3 years
        "2023-11-01, JUNIOR,   2.9",   // < 3 years
        "2020-01-14, MID,      6.7",   // 3–7 years
        "2018-07-22, MID,      8.1",   // actually just over 8 → SENIOR
        "2015-09-10, SENIOR,  11.0",   // 8–14 years
        "2010-03-15, SENIOR,  16.5",   // actually > 15 → VETERAN
        "1998-04-02, VETERAN, 28.4"    // 15+ years
    })
    @DisplayName("Band classification matches COBOL EVALUATE thresholds")
    void testBandClassification(String hireDateStr, String expectedBand,
                                double expectedYearsApprox) {
        Employee emp = new Employee(1, "Test Employee",
                LocalDate.parse(hireDateStr));
        SenioritySummary summary = new SenioritySummary();

        SeniorityRecord rec = service.calcService(emp, summary);

        assertThat(rec.getBand())
                .as("Band for hire date %s", hireDateStr)
                .isEqualTo(expectedBand);
        assertThat(rec.getYearsOfService())
                .as("Years of service for hire date %s", hireDateStr)
                .isCloseTo(expectedYearsApprox, within(0.5));
    }

    @Test
    @DisplayName("Summary counters are incremented correctly")
    void testSummaryCounters() {
        SenioritySummary summary = new SenioritySummary();

        callCalc(summary, "2024-08-19"); // JUNIOR
        callCalc(summary, "2023-11-01"); // JUNIOR
        callCalc(summary, "2020-01-14"); // MID
        callCalc(summary, "2015-09-10"); // SENIOR
        callCalc(summary, "1998-04-02"); // VETERAN
        callCalc(summary, "2000-01-01"); // VETERAN

        assertThat(summary.getJunior()).isEqualTo(2);
        assertThat(summary.getMid()).isEqualTo(1);
        assertThat(summary.getSenior()).isEqualTo(1);
        assertThat(summary.getVeteran()).isEqualTo(2);
    }

    @Test
    @DisplayName("Years calculation exactly mirrors COBOL days/365.25")
    void testYearsCalculation() {
        // hire 2010-03-15, as-of 2026-09-29
        // days = LocalDate(2026,9,29).toEpochDay() - LocalDate(2010,3,15).toEpochDay()
        long expected_days = LocalDate.of(2026, 9, 29).toEpochDay()
                           - LocalDate.of(2010, 3, 15).toEpochDay();
        double expectedYears = Math.floor((expected_days / 365.25) * 10.0) / 10.0;

        Employee emp = new Employee(1, "Alice", LocalDate.of(2010, 3, 15));
        SeniorityRecord rec = service.calcService(emp, new SenioritySummary());

        assertThat(rec.getYearsOfService()).isEqualTo(expectedYears);
    }

    private void callCalc(SenioritySummary summary, String hireDate) {
        service.calcService(
                new Employee(1, "Test", LocalDate.parse(hireDate)),
                summary);
    }
}

