package com.example.seniority.service;

import com.example.seniority.dto.SeniorityRecord;
import com.example.seniority.dto.SeniorityReport;
import com.example.seniority.dto.SenioritySummary;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

class ReportWriterServiceTest {

    @TempDir
    Path tempDir;

    @Test
    void reportContainsTitleAndSeparators() throws Exception {
        ReportWriterService writer = buildWriter(tempDir.resolve("out/seniority.rpt").toString());

        SenioritySummary summary = new SenioritySummary();
        summary.incrementJunior();
        SeniorityRecord rec = new SeniorityRecord(
                10001, "Alice Johnson",
                LocalDate.of(2024, 8, 19), 2.1, "JUNIOR");
        SeniorityReport report = new SeniorityReport(List.of(rec), summary);

        writer.write(report);

        List<String> lines = Files.readAllLines(
                tempDir.resolve("out/seniority.rpt"));
        assertThat(lines.get(0)).contains("SENIORITY REPORT AS OF 2026-09-29");
        assertThat(lines.get(1)).startsWith("----");
        assertThat(lines.get(2)).contains("ID").contains("NAME").contains("HIRE DATE");
        // detail line present
        boolean hasDetail = lines.stream().anyMatch(l -> l.contains("10001"));
        assertThat(hasDetail).isTrue();
        // summary present
        boolean hasSummary = lines.stream().anyMatch(l -> l.contains("JUNIOR"));
        assertThat(hasSummary).isTrue();
    }

    private ReportWriterService buildWriter(String path) throws Exception {
        ReportWriterService svc = new ReportWriterService();
        // inject path via reflection (field is @Value-injected in prod)
        var field = ReportWriterService.class.getDeclaredField("outputPath");
        field.setAccessible(true);
        field.set(svc, path);
        return svc;
    }
}

